// Pages to measure. Keep in step with weberact/sitemap.xml.
const base = 'https://weberact.co/';
const pages = ['', 'services.html', 'website-development.html', 'technical-seo.html', 'ai-automation.html', 'b2b-lead-generation.html', 'international.html', 'proposal.html'];
return pages.map(p => ({ json: { url: base + p } }));

// Field data (real users, CrUX) when Google has enough of it; lab data always.
return $input.all().map(i => {
  const d = i.json, f = (d.loadingExperience || {}).metrics || {}, a = d.lighthouseResult.audits;
  const p75 = k => f[k] ? f[k].percentile : '';
  return { json: {
    date: new Date().toISOString().slice(0, 10), url: d.id,
    field_lcp_ms: p75('LARGEST_CONTENTFUL_PAINT_MS'), field_inp_ms: p75('INTERACTION_TO_NEXT_PAINT'), field_cls_x100: p75('CUMULATIVE_LAYOUT_SHIFT_SCORE'),
    lab_performance: Math.round(d.lighthouseResult.categories.performance.score * 100),
    lab_lcp_ms: Math.round(a['largest-contentful-paint'].numericValue), lab_cls: a['cumulative-layout-shift'].numericValue,
    lab_tbt_ms: Math.round(a['total-blocking-time'].numericValue)
  } };
});
